// Exclusion reasons as the builds record them, in Japanese.
const REASON_JA={'special transaction circumstances':'特殊な事情のある取引','explicit non-residential use':'住宅以外の用途','invalid or censored price/area':'価格・面積が無効または秘匿','not a house (other or unknown building use)':'戸建て住宅以外（その他または不明な用途）','not in a residential zone':'住宅地以外','additional price paid sales (category B: repossessions, company and buy-to-let transfers)':'追加的な取引（カテゴリーB：差し押さえ、法人・賃貸投資用の移転）','other property types':'その他の物件種別','floor area missing or outside 10–1,000 m²':'床面積が不明、または10〜1,000㎡の範囲外'};
const reasons=x=>Object.entries(x).map(([r,v])=>JA?`${esc(REASON_JA[r]||r)} ${fmt(v)}件`:`${fmt(v)} with ${esc(r)}`).join(J('; ','、')),heads=h=>`<thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead>`;
function londonCoverage(){const c=D.coverage,k=c.counts,years=Object.entries(c.by_year).filter(([y])=>+y>=2006),miss=Object.values(c.type_mismatch).reduce((x,y)=>x+y,0);
const table=`<div class="tablewrap"><table>${heads(JA?['年','Land Registry の取引','床面積あり','割合','使用']:['Year','Land Registry sales','With floor area','Share','Used'])}<tbody>${years.map(([y,v])=>`<tr><td>${y}</td><td>${fmt(v.ppd)}</td><td>${fmt(v.eligible)}</td><td>${v.ppd?Math.round(100*v.eligible/v.ppd)+'%':'—'}</td><td>${fmt(v.used||0)}</td></tr>`).join('')}</tbody></table></div>`;
return JA?`<p>2026年10月24日作成、2024年10月までの取引によります。対象地域の${fmt(c.districts)}自治体で1995年以降の取引${fmt(k.raw)}件に、エネルギー性能証明書の床面積があります。そのうち${fmt(k.in_windows)}件が2006年以降の期間にあり、${fmt(c.sites_shown)}駅のいずれかから${c.radius_km} km以内にあります。</p>${table}<p>Land Registry の取引は、対象地域のフラットとハウスの通常取引（カテゴリーA）です。使っていないもの：駅から${c.radius_km} kmより遠い取引${fmt(k['more than 1.2 km from a station'])}件、対象地域外の駅が最寄りの取引${fmt(k['nearest station outside the atlas area'])}件、2006年より前または2024年の取引${fmt(k['outside windows'])}件、${reasons(D.exclusions)}。フラットかハウスかについて Land Registry と証明書の記載が異なるのは取引の${(100*miss/k.eligible).toFixed(1)}%です。</p>`
:`<p>Built 24 October 2026 from sales up to October 2024. ${fmt(k.raw)} sales since 1995 in the atlas area's ${fmt(c.districts)} councils have a floor area from an energy certificate. ${fmt(k.in_windows)} of them fall in the windows from 2006 and within ${c.radius_km} km of one of ${fmt(c.sites_shown)} stations.</p>${table}<p>Land Registry sales are standard (category A) sales of flats and houses in the atlas area. Not used: ${fmt(k['more than 1.2 km from a station'])} sales more than ${c.radius_km} km from a station, ${fmt(k['nearest station outside the atlas area'])} nearest a station outside the atlas area, ${fmt(k['outside windows'])} before 2006 or in 2024, and ${reasons(D.exclusions)}. The Land Registry and the certificate disagree on flat versus house for ${(100*miss/k.eligible).toFixed(1)}% of sales.</p>`}
function japanCoverage(){const hid=c=>!D.prefectures[c],pn=c=>D.prefectures[c]?prefLabel(c):D.coverage[c].name,ns=J(' <small>(not shown)</small>',' <small>（非表示）</small>');
return `<p>${J('Downloaded 24 October 2026. ','2026年10月24日にダウンロード。')}${T(E.scope)}${J(' Station matching and eligibility losses are shown below.','駅の照合と対象外となった件数は以下のとおりです。')}</p><div class="tablewrap"><table>${heads(JA?['都道府県','元データ','対象','照合済み','2006〜25年']:['Prefecture','Source','Eligible','Matched','2006–25'])}<tbody>`+Object.entries(D.coverage).sort(([a,x],[b,y])=>hid(a)-hid(b)||y.raw-x.raw).map(([code,c])=>`<tr><td>${esc(pn(code))}${hid(code)?ns:''}</td><td>${fmt(c.raw)}</td><td>${fmt(c.eligible)}</td><td>${fmt(c.matched)}</td><td>${fmt(c.in_windows)}</td></tr>`).join('')+`</tbody></table></div><p>${J('Eligible records exclude ','対象件数からは次を除いています：')}${JA?reasons(D.exclusions):Object.entries(D.exclusions).map(([r,v])=>`${fmt(v)} ${esc(r)}`).join('; ')}${J('.','。')}</p>`+(D.type_coverage?`<p>${J('Houses and land: sales in the 2006–25 windows, after the same exclusions.','戸建てと土地：2006〜25年の期間の取引（同じ除外の後）。')}</p><div class="tablewrap"><table>${heads(JA?['都道府県','戸建て','土地']:['Prefecture','Houses','Land'])}<tbody>`+Object.entries(D.type_coverage).map(([c,v])=>`<tr><td>${D.prefectures[c]?esc(pn(c)):esc(D.hidden_prefectures[c])+ns}</td><td>${fmt((v.houses||{}).in_windows)}</td><td>${fmt((v.land||{}).in_windows)}</td></tr>`).join('')+'</tbody></table></div>':'')}
